package com.enterprise.licensing.storage.repository;
import com.enterprise.licensing.crypto.CanonicalJson;import com.enterprise.licensing.engine.audit.AuditRepository;import com.enterprise.licensing.engine.ports.TransactionRunner;import com.enterprise.licensing.model.*;import com.enterprise.licensing.storage.sqlite.*;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.ResultSet;import java.time.Instant;import java.util.*;
public final class SqliteAuditRepository implements AuditRepository{private final SqliteDatabase database;private final TransactionRunner transactions;private final ObjectMapper mapper;private final CanonicalJson canonical;
 public SqliteAuditRepository(SqliteDatabase d,TransactionRunner t,ObjectMapper m){database=d;transactions=t;mapper=m;canonical=new CanonicalJson(m);}
 @Override public AuditEvent append(UUID id,Instant at,String customer,String license,String instance,LicenseOperation operation,String entitlement,boolean allowed,LicenseReasonCode reason,Map<String,String>context){return transactions.write(()->{String previous=lastHash();String eventHash=hash(id,at,customer,license,instance,operation,entitlement,allowed,reason,context,previous);execute("INSERT INTO audit_event(audit_id,occurred_at,customer_id,license_id,instance_id,operation,entitlement,allowed,reason_code,context_json,previous_hash,event_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id.toString(),at.toString(),customer,license,instance,operation.name(),entitlement,allowed?1:0,reason.name(),json(context),previous,eventHash);return new AuditEvent(id,at,customer,license,instance,operation,entitlement,allowed,reason,context,previous,eventHash);});}
 @Override public List<AuditEvent> page(int offset,int limit){if(offset<0||limit<1||limit>1000)throw new IllegalArgumentException("invalid audit page");return transactions.read(()->database.withConnection(c->{try(var s=c.prepareStatement("SELECT * FROM audit_event ORDER BY occurred_at,audit_id LIMIT ? OFFSET ?")){s.setInt(1,limit);s.setInt(2,offset);try(var r=s.executeQuery()){var values=new ArrayList<AuditEvent>();while(r.next())values.add(map(r));return List.copyOf(values);}}catch(Exception e){throw failure(e);}}));}
 @Override public boolean verifyChain(){return transactions.read(()->database.withConnection(c->{try(var s=c.prepareStatement("SELECT * FROM audit_event ORDER BY rowid");var r=s.executeQuery()){String previous=null;while(r.next()){var event=map(r);if(!Objects.equals(previous,event.previousHash())||!event.eventHash().equals(hash(event.auditId(),event.occurredAt(),event.customerId(),event.licenseId(),event.instanceId(),event.operation(),event.entitlement(),event.allowed(),event.reasonCode(),event.context(),event.previousHash())))return false;previous=event.eventHash();}return true;}catch(Exception e){throw failure(e);}}));}
 private String lastHash(){return database.withConnection(c->{try(var s=c.prepareStatement("SELECT event_hash FROM audit_event ORDER BY rowid DESC LIMIT 1");var r=s.executeQuery()){return r.next()?r.getString(1):null;}catch(Exception e){throw failure(e);}});}
 private String hash(UUID id,Instant at,String customer,String license,String instance,LicenseOperation op,String entitlement,boolean allowed,LicenseReasonCode reason,Map<String,String>context,String previous){try{var values=new LinkedHashMap<String,Object>();values.put("auditId",id);values.put("occurredAt",at);values.put("customerId",customer);values.put("licenseId",license);values.put("instanceId",instance);values.put("operation",op);values.put("entitlement",entitlement);values.put("allowed",allowed);values.put("reasonCode",reason);values.put("context",context);values.put("previousHash",previous);return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.canonicalize(values)));}catch(Exception e){throw failure(e);}}
 private AuditEvent map(ResultSet r)throws Exception{return new AuditEvent(UUID.fromString(r.getString("audit_id")),Instant.parse(r.getString("occurred_at")),r.getString("customer_id"),r.getString("license_id"),r.getString("instance_id"),LicenseOperation.valueOf(r.getString("operation")),r.getString("entitlement"),r.getInt("allowed")==1,LicenseReasonCode.valueOf(r.getString("reason_code")),mapper.readValue(r.getString("context_json"),new TypeReference<Map<String,String>>(){}),r.getString("previous_hash"),r.getString("event_hash"));}
 private void execute(String sql,Object...v){database.withConnection(c->{try(var s=c.prepareStatement(sql)){for(int i=0;i<v.length;i++)s.setObject(i+1,v[i]);s.executeUpdate();return null;}catch(Exception e){throw failure(e);}});}private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw failure(e);}}private static SqliteStorageException failure(Exception e){return new SqliteStorageException("Audit persistence failure",e);}
}
